package dev.gbppimentel.sessionhome;
import android.app.*;import android.content.*;import android.os.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.io.*;import java.nio.channels.*;import java.nio.file.Files;import java.lang.reflect.*;import java.security.MessageDigest;import java.util.*;
/** Metadata-only, one-shot resume repair. Runs through the Thor firmware service while Home. */
public final class SessionReturn {
 static final File DIR=new File("/data/user/0/dev.gbppimentel.sessionhome/files"),PAIR=new File(DIR,"suspended-pair.json");
 static Object service;static Method tasks;
 static final class Task {int id;String pkg,component,fingerprint;boolean visible;}
 static void init()throws Exception{service=Class.forName("android.app.ActivityTaskManager").getDeclaredMethod("getService").invoke(null);tasks=service.getClass().getMethod("getTasks",int.class,boolean.class,boolean.class,int.class);}
 static List<Task> list(int display)throws Exception{List<Task> out=new ArrayList<>();for(Object v:(List<?>)tasks.invoke(service,40,false,true,display)){ComponentName c=(ComponentName)v.getClass().getField("topActivity").get(v);if(c==null)continue;Task t=new Task();t.id=v.getClass().getField("taskId").getInt(v);t.pkg=c.getPackageName();Intent i=(Intent)v.getClass().getField("baseIntent").get(v);ComponentName base=i.getComponent();t.component=(base==null?c:base).flattenToString();t.fingerprint=fingerprint(i);try{t.visible=v.getClass().getField("isVisible").getBoolean(v);}catch(Exception ignored){t.visible=true;}out.add(t);}return out;}
 static String fingerprint(Intent intent)throws Exception{Intent stable=new Intent(intent);stable.setFlags(0);stable.setSourceBounds(null);try{return hash(stable.toUri(0));}catch(RuntimeException privateParcelable){return hash(String.valueOf(stable.getComponent())+"|"+stable.getAction()+"|"+stable.getDataString());}}
 static String hash(String s)throws Exception{byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8"));char[] h=new char[b.length*2],hex="0123456789abcdef".toCharArray();for(int i=0;i<b.length;i++){h[i*2]=hex[(b[i]&255)>>>4];h[i*2+1]=hex[b[i]&15];}return new String(h);}
 static Task visible(List<Task> ts){for(Task t:ts)if(t.visible&&!t.pkg.equals("dev.gbppimentel.sessionhome"))return t;return null;}
 static boolean home(Task t){return t==null||t.pkg.equals("rip.moth.cocoonshell")||t.pkg.equals("com.android.launcher3");}
 static boolean configuredCompanion(String pkg){try(SQLiteDatabase db=SQLiteDatabase.openDatabase("/data/user/0/rip.moth.cocoonshell/databases/cocoon_db",null,SQLiteDatabase.OPEN_READONLY);Cursor c=db.rawQuery("SELECT 1 FROM games WHERE companionAppPackage=? LIMIT 1",new String[]{pkg})){return c.moveToFirst();}catch(Exception e){return false;}}
 static void write(File target,JSONObject j)throws Exception{File tmp=new File(DIR,target.getName()+".next");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(j.toString().getBytes("UTF-8"));}tmp.setReadable(true,false);if(!tmp.renameTo(target))throw new IOException("Cannot publish session metadata");}
 static void status(String value)throws Exception{write(new File(DIR,"return-status.json"),new JSONObject().put("at",System.currentTimeMillis()).put("state",value));}
 static String boot()throws Exception{return new String(Files.readAllBytes(new File("/proc/sys/kernel/random/boot_id").toPath()),"UTF-8").trim();}
 static boolean running(String pkg)throws Exception{java.lang.Process p=new ProcessBuilder("/system/bin/pidof",pkg).start();try(InputStream in=p.getInputStream()){byte[] b=new byte[256];while(in.read(b)!=-1){}}return p.waitFor()==0;}
 static void capture()throws Exception{Task top=visible(list(0)),bottom=visible(list(4));if(home(top))return;if(home(bottom)||!configuredCompanion(bottom.pkg)){PAIR.delete();return;}write(PAIR,new JSONObject().put("boot",boot()).put("at",System.currentTimeMillis()).put("task",top.id).put("package",top.pkg).put("fingerprint",top.fingerprint).put("companionTask",bottom.id).put("companion",bottom.pkg).put("component",bottom.component));status("Suspended");}
 static boolean same(Task t,JSONObject p){return t!=null&&t.id==p.optInt("task")&&t.pkg.equals(p.optString("package"))&&t.fingerprint.equals(p.optString("fingerprint"));}
 static void command(String...args)throws Exception{java.lang.Process p=new ProcessBuilder(args).redirectErrorStream(true).start();try(InputStream in=p.getInputStream()){byte[] b=new byte[2048];while(in.read(b)!=-1){}}if(p.waitFor()!=0)throw new IOException("Session action failed");}
 static void front(int task,int display)throws Exception{try{service.getClass().getMethod("moveRootTaskToDisplay",int.class,int.class).invoke(service,task,display);}catch(Exception ignored){}Method m=service.getClass().getMethod("startActivityFromRecents",int.class,Bundle.class);ActivityOptions o=ActivityOptions.makeBasic();o.setLaunchDisplayId(display);m.invoke(service,task,o.toBundle());}
 static void finishRestore(JSONObject p,String state)throws Exception{front(p.getInt("task"),0);command("settings","put","system","screen_focus_lock","1");status(state);}
 static void restore(JSONObject p,List<Task> bottom)throws Exception{Task current=visible(bottom);if(!home(current)){finishRestore(p,"Pair Already Present");return;}
  for(Task t:list(-1))if(t.id==p.optInt("companionTask")&&t.pkg.equals(p.optString("companion"))){try{front(t.id,4);finishRestore(p,"Pair Tasks Restored");return;}catch(Exception ignored){break;}}
  // An APK update may replace the task. Reopen the recorded launcher component as a fallback.
  command("am","start","--display","4","-f","0x10060000","-n",p.getString("component"));finishRestore(p,"Companion Reopened");
 }
 static void watch()throws Exception{try(RandomAccessFile f=new RandomAccessFile(new File(DIR,"return.lock"),"rw");FileLock lock=f.getChannel().tryLock()){if(lock==null)return;long generation=0,visibleSince=0,missingSince=0;JSONObject pair=null;boolean waiting=true;String currentBoot=boot();while(PAIR.exists()){
   JSONObject next=new JSONObject(new String(Files.readAllBytes(PAIR.toPath()),"UTF-8"));if(!currentBoot.equals(next.optString("boot"))){PAIR.delete();status("Previous Boot Released");return;}if(next.optLong("at")!=generation){pair=next;generation=next.optLong("at");visibleSince=0;missingSince=0;waiting=true;}
   Task current=visible(list(0));boolean exists=false,packageExists=false;for(Task t:list(-1)){if(same(t,pair))exists=true;if(t.pkg.equals(pair.optString("package")))packageExists=true;}
   if(!exists){if(missingSince==0)missingSince=SystemClock.elapsedRealtime();int action=SessionPolicy.missing(false,packageExists,running(pair.getString("package")),SystemClock.elapsedRealtime()-missingSince);if(action!=SessionPolicy.KEEP){if(action==SessionPolicy.CLOSE_COMPANION&&configuredCompanion(pair.optString("companion")))command("am","force-stop",pair.getString("companion"));status(action==SessionPolicy.CLOSE_COMPANION?"Pair Closed":"Different Game Task Released");PAIR.delete();return;}Thread.sleep(200);continue;}missingSince=0;
   if(waiting){if(home(current))visibleSince=0;else if(same(current,pair)){if(visibleSince==0)visibleSince=SystemClock.elapsedRealtime();if(SystemClock.elapsedRealtime()-visibleSince>=900){restore(pair,list(4));waiting=false;}}else if(current!=null&&!current.pkg.equals("dev.gbppimentel.sessionhome")){waiting=false;status("Different App Selected");}}
   Thread.sleep(waiting?200:600);
  }}}

 public static void main(String[] args){try{init();if(args.length>0&&args[0].equals("capture"))capture();else if(args.length==3&&args[0].equals("front")){front(Integer.parseInt(args[1]),Integer.parseInt(args[2]));status("Task Restored");}else watch();}catch(Throwable e){try{status("Resume Repair Unavailable: "+e.getClass().getSimpleName());}catch(Exception ignored){}}finally{Runtime.getRuntime().halt(0);}}
}
